export const LEGACY_VINBOX_UI_TOOL_NAME = "vinbox_ui";
export const VINBOX_UI_CLIENT_TOOL_NAME = "vinbox_ui_control";

/**
 * Action discriminator generated by the SDK for the client-defined Vinbox UI
 * tool (`ClientAction_<tool-name>`). Keep the SDK naming convention contained
 * here instead of repeating its generated class name throughout the frontend.
 */
export const VINBOX_UI_CLIENT_ACTION_KIND =
  `ClientAction_${VINBOX_UI_CLIENT_TOOL_NAME}` as const;
